contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable {
        require(address(this) == address(this));
        uint beforeC = address(c).balance;
        uint beforeR = address(receiver).balance;
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterC = address(c).balance;
        uint afterR = address(receiver).balance;
        assert((reverted && afterC == beforeC && afterR == beforeR) || (!reverted && afterC == beforeC - amount && afterR == beforeR + amount));
    }

    receive() external payable {}
}

